"""`.Tex General`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Tex General'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Main texture', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Main texture (alpha)', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Main texture (plain)', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Main texture (dark)', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Color mask', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
