    t.socket('OUTPUT', 'Detail mask', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Pattern (base)', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
